19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE = 0.1;
21	
22	/** Premiums are rounded up (in the MHPCO's favour), ignoring float noise. */
23	const roundUp = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
24	
25	const BASE_PREMIUMS: Record<string, number> = {
26	  sword: 100,
27	  amulet: 60,
28	  staff: 80,
29	};
30	
31	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
32	
33	const quotePremium = (step: QuoteStep): number => {
34	  const policyBasePremium = step.items.reduce(
35	    (sum, item) => sum + itemBasePremium(item),
36	    0,
37	  );
38	  const afterPolicyModifiers =
39	    policyBasePremium * (1 + FIRST_INSURANCE_SURCHARGE);
40	
41	  return roundUp(afterPolicyModifiers + PROCESSING_FEE);
42	};
43	
44	export const runScenario = (scenario: Scenario): ScenarioResults => ({
45	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
46	});
